describe('maskNonMarkup', () => {
  it('masks a regex literal after typeof', () => {
    expect(maskNonMarkup('{typeof /<br>/}')).toBe('{typeof /    /}');
  });

  it('masks template strings but keeps the code inside ${}', () => {
    expect(maskNonMarkup('{`a\n\n${x + "<hr>"}\n\nb`}')).toBe('{` \n\n${x + "    "}\n\n `}');
  });

  it('keeps masking after an expression the tokenizer rejects', () => {
    expect(maskNonMarkup('## A {#1-intro}\n\n{"<br>"}')).toBe('## A {#1-intro}\n\n{"    "}');
  });

  it('blanks an escaped tag and does not open an expression at an escaped brace', () => {
    expect(maskNonMarkup('\\<br> \\{"<br>"} {"<br>"}')).toBe('\\ br> \\{"<br>"} {"    "}');
  });
});

describe('toParseError', () => {
  it('reads the position from the reason of an unclosed JSX tag', () => {
    let error: unknown;
    try {
      getAST('---\ntitle: A\n---\n\n<Note>\nunclosed\n', 'a.mdx');
    } catch (caught) {
      error = caught;
    }

    expect(toParseError(error)).toEqual({
      line: 5,
      column: 1,
      message: 'Expected a closing tag for `<Note>`',
    });
  });
});

describe('applyEdits', () => {
  it('keeps a replacement that an insertion at its start precedes', () => {
    expect(
      applyEdits('a<br>b', [
        { start: 1, end: 5, text: '<br />' },
        { start: 1, end: 1, text: 'x' },
      ])
    ).toBe('ax<br />b');
  });
});

describe('mapping back through edits', () => {
  const inserted = [
    { content: 'ab', edits: [{ start: 1, end: 1, text: 'XY' }] },
    { content: 'aXYb', edits: [] },
  ];
  const deleted = [
    { content: 'aXYb', edits: [{ start: 1, end: 3, text: '' }] },
    { content: 'ab', edits: [] },
  ];

  it('snaps positions at or inside inserted text to the insertion point', () => {
    expect(relocate(inserted, 1, { line: 1, column: 2 })).toEqual({ line: 1, column: 2 });
    expect(relocate(inserted, 1, { line: 1, column: 3 })).toEqual({ line: 1, column: 2 });
    expect(relocate(inserted, 1, { line: 1, column: 5 })).toEqual({ line: 1, column: 3 });
  });

  it('places a position at a deletion after the deleted text', () => {
    expect(relocate(deleted, 1, { line: 1, column: 2 })).toEqual({ line: 1, column: 4 });
  });

  it('maps an edit at an insertion point to before the inserted text and rejects one inside it', () => {
    expect(unmapEdit(inserted, 1, { start: 1, end: 1, text: 'Z' })).toEqual({
      start: 1,
      end: 1,
      text: 'Z',
    });
    expect(unmapEdit(inserted, 1, { start: 2, end: 2, text: 'Z' })).toBeUndefined();
    expect(unmapEdit(inserted, 1, { start: 3, end: 3, text: 'Z' })).toEqual({
      start: 1,
      end: 1,
      text: 'Z',
    });
  });

  it('maps an edit at a deletion point to before the deleted text', () => {
    expect(unmapEdit(deleted, 1, { start: 1, end: 1, text: 'Z' })).toEqual({
      start: 1,
      end: 1,
      text: 'Z',
    });
  });
});
